'use client';

import React, { useState, useEffect } from 'react';

interface IpoCompanyLogoProps {
  src?: string | null;
  name: string;
  size?: 'sm' | 'md' | 'lg' | 'xl';
  className?: string;
}

export function IpoCompanyLogo({
  src,
  name,
  size = 'md',
  className = '',
}: IpoCompanyLogoProps) {
  const [hasError, setHasError] = useState(false);

  useEffect(() => {
    setHasError(false);
  }, [src]);

  const sizeClasses = {
    sm: 'w-7 h-7 text-[10px] rounded-lg',
    md: 'w-8 h-8 text-xs rounded-lg',
    lg: 'w-12 h-12 text-base rounded-xl',
    xl: 'w-16 h-16 text-2xl rounded-2xl',
  }[size];

  const initials = (name || 'IP').slice(0, 2).toUpperCase();

  if (src && !hasError) {
    return (
      <div
        className={`relative ${sizeClasses} shrink-0 overflow-hidden flex items-center justify-center border border-slate-200/80 dark:border-slate-700/80 bg-white dark:bg-slate-900 p-0.5 shadow-2xs transition-all ${className}`}
      >
        <img
          src={src}
          alt={name}
          loading="lazy"
          className="w-full h-full object-contain"
          onError={() => setHasError(true)}
        />
      </div>
    );
  }

  return (
    <div
      className={`${sizeClasses} bg-slate-100 dark:bg-slate-800 border border-slate-200 dark:border-slate-700/80 flex items-center justify-center font-bold text-xs text-sky-600 dark:text-sky-400 group-hover:border-sky-500/50 transition-all shrink-0 select-none ${className}`}
      title={name}
    >
      {initials}
    </div>
  );
}

export default IpoCompanyLogo;

'use client';

import { useState } from 'react';
import { IPOSubscriptionCategory, IPOSubscriptionSummary } from '../types';
import { TrendingUp, Layers, PieChart, Calendar, Coins, Clock, ArrowUpRight } from 'lucide-react';

interface SubscriptionTabsSectionProps {
  companyName: string;
  subscriptions?: IPOSubscriptionCategory[];
  subscriptionSummary?: IPOSubscriptionSummary | null;
  overallTimes?: number | null;
  overallDisplay?: string | null;
  fundingInterestCost?: Record<string, number> | null;
}

export function SubscriptionTabsSection({
  companyName,
  subscriptions = [],
  subscriptionSummary,
  overallTimes,
  overallDisplay,
  fundingInterestCost,
}: SubscriptionTabsSectionProps) {
  const [activeTab, setActiveTab] = useState<'shares' | 'demand' | 'applications' | 'daywise' | 'funding'>('shares');

  const hasSummaryShares = Boolean(subscriptionSummary?.by_shares && subscriptionSummary.by_shares.length > 0);
  const hasDemand = Boolean(subscriptionSummary?.by_demand_cr && subscriptionSummary.by_demand_cr.length > 0);
  const hasApplications = Boolean(subscriptionSummary?.by_applications && subscriptionSummary.by_applications.length > 0);
  const hasDayWise = Boolean(subscriptionSummary?.day_wise && subscriptionSummary.day_wise.length > 0);
  const fundingCosts = fundingInterestCost || subscriptionSummary?.funding_interest_cost;
  const hasFunding = Boolean(fundingCosts && Object.keys(fundingCosts).length > 0);

  // Fallback unique subscriptions from subscriptions array if by_shares not directly present
  const fallbackShares = subscriptions
    .filter((s) => !s.sub_type || s.sub_type === 'shares')
    .filter((s, idx, arr) => arr.findIndex((t) => t.category === s.category) === idx);

  const displayTimes = overallDisplay || (overallTimes ? `${overallTimes}x` : '–');

  return (
    <section id="subscription" className="bg-white dark:bg-slate-900/90 border border-slate-200 dark:border-slate-800 rounded-2xl p-5 md:p-6 shadow-sm dark:shadow-lg">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3 mb-5">
        <div className="flex items-center gap-2">
          <TrendingUp className="w-5 h-5 text-sky-600 dark:text-sky-400" />
          <div>
            <h2 className="text-lg font-bold text-slate-900 dark:text-slate-100">{companyName} IPO Live Subscription Status</h2>
            <span className="text-xs text-slate-500 dark:text-slate-400">
              Bidding demand breakdown by shares, institutional demand in ₹ Cr, applications &amp; HNI funding cost
            </span>
          </div>
        </div>

        <div className="flex items-center gap-3 flex-wrap">
          <div className="flex items-center gap-2 bg-sky-50 dark:bg-sky-500/15 border border-sky-200 dark:border-sky-500/30 px-3.5 py-1.5 rounded-xl text-xs">
            <span className="text-slate-500 dark:text-slate-400 font-medium">Overall Demand:</span>
            <span className="font-extrabold text-sky-600 dark:text-sky-400 text-sm tabular-nums">{displayTimes}</span>
          </div>
          {subscriptionSummary?.last_updated_at && (
            <div className="text-[11px] text-slate-400 dark:text-slate-500 flex items-center gap-1">
              <Clock className="w-3 h-3 text-slate-400" />
              <span>{new Date(subscriptionSummary.last_updated_at).toLocaleTimeString('en-IN', { hour: '2-digit', minute: '2-digit' })}</span>
            </div>
          )}
        </div>
      </div>

      {/* Interactive Tabs Header */}
      <div className="flex items-center gap-2 border-b border-slate-200 dark:border-slate-800 pb-3 mb-4 overflow-x-auto no-scrollbar text-xs">
        <button
          onClick={() => setActiveTab('shares')}
          className={`px-3.5 py-2 rounded-xl font-semibold transition-all flex items-center gap-1.5 whitespace-nowrap ${
            activeTab === 'shares'
              ? 'bg-sky-50 dark:bg-sky-500/20 text-sky-700 dark:text-sky-300 border border-sky-200 dark:border-sky-500/40 shadow-xs'
              : 'bg-slate-100 dark:bg-slate-800/80 text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-slate-200 border border-slate-200 dark:border-slate-700/60'
          }`}
        >
          <Layers className="w-3.5 h-3.5 text-sky-600 dark:text-sky-400" />
          <span>By Shares</span>
        </button>

        {hasDemand && (
          <button
            onClick={() => setActiveTab('demand')}
            className={`px-3.5 py-2 rounded-xl font-semibold transition-all flex items-center gap-1.5 whitespace-nowrap ${
              activeTab === 'demand'
                ? 'bg-emerald-50 dark:bg-emerald-500/20 text-emerald-700 dark:text-emerald-300 border border-emerald-200 dark:border-emerald-500/40 shadow-xs'
                : 'bg-slate-100 dark:bg-slate-800/80 text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-slate-200 border border-slate-200 dark:border-slate-700/60'
            }`}
          >
            <PieChart className="w-3.5 h-3.5 text-emerald-600 dark:text-emerald-400" />
            <span>Demand in ₹ Cr (FII / DII)</span>
          </button>
        )}

        {hasApplications && (
          <button
            onClick={() => setActiveTab('applications')}
            className={`px-3.5 py-2 rounded-xl font-semibold transition-all flex items-center gap-1.5 whitespace-nowrap ${
              activeTab === 'applications'
                ? 'bg-purple-50 dark:bg-purple-500/20 text-purple-700 dark:text-purple-300 border border-purple-200 dark:border-purple-500/40 shadow-xs'
                : 'bg-slate-100 dark:bg-slate-800/80 text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-slate-200 border border-slate-200 dark:border-slate-700/60'
            }`}
          >
            <Coins className="w-3.5 h-3.5 text-purple-600 dark:text-purple-400" />
            <span>By Applications</span>
          </button>
        )}

        {hasDayWise && (
          <button
            onClick={() => setActiveTab('daywise')}
            className={`px-3.5 py-2 rounded-xl font-semibold transition-all flex items-center gap-1.5 whitespace-nowrap ${
              activeTab === 'daywise'
