"use client";

/**
 * HistoryChartSection Component
 * Complete history chart section with controls
 */

import { useState, useEffect, useCallback, useRef } from "react";
import { TrendingUp } from "lucide-react";
import { HistoryChart } from "./HistoryChart";
import { HistoryControls } from "./HistoryControls";
import type {
  Metal,
  MetalPurity,
  MetalUnit,
  ChartDuration,
  ChartPoint,
} from "../types";
import { METAL_CONFIG, CHART_DURATIONS } from "../types";

interface HistoryChartSectionProps {
  metal: Metal;
  citySlug: string;
  initialData: ChartPoint[];
  initialPurity?: MetalPurity;
  initialUnit: MetalUnit;
  initialDuration: ChartDuration;
}

export function HistoryChartSection({
  metal,
  citySlug,
  initialData,
  initialPurity,
  initialUnit,
  initialDuration,
}: HistoryChartSectionProps) {
  const metalConfig = METAL_CONFIG[metal];
  const historyUnits = metalConfig.historyUnits || metalConfig.units;

  const [purity, setPurity] = useState<MetalPurity | undefined>(
    metal === "gold" ? initialPurity : undefined
  );
  const [unit, setUnit] = useState<MetalUnit>(initialUnit);
  const [duration, setDuration] = useState<ChartDuration>(initialDuration);
  const [chartData, setChartData] = useState<ChartPoint[]>(initialData);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Track initial mount so SSR initialData is used initially,
  // but ANY subsequent change (including returning to initial settings) triggers an API call
  const isFirstMount = useRef(true);

  // When switching metal or city, sync to new initial props
  useEffect(() => {
    setPurity(metal === "gold" ? initialPurity : undefined);
    setUnit(initialUnit);
    setDuration(initialDuration);
    setChartData(initialData);
    isFirstMount.current = true;
  }, [metal, citySlug, initialPurity, initialUnit, initialDuration, initialData]);

  const fetchChartData = useCallback(async () => {
    setLoading(true);
    setError(null);

    try {
      // In case of platinum, show 9m data by default; even if user selects 1w, 1m, 3m, 6m, query 9m data; 1y will be 1y
      const effectiveDuration: ChartDuration =
        metal === "platinum" && duration !== "1y" ? "9m" : duration;

      const params = new URLSearchParams({
        metal,
        citySlug,
        unit,
        duration: effectiveDuration,
      });

      // Strictly only append purity for gold
      if (metal === "gold" && purity) {
        params.append("purity", purity);
      }

      const response = await fetch(`/api/metals/history?${params.toString()}`);

      if (!response.ok) {
        throw new Error("Failed to fetch chart data");
      }

      const result = await response.json();
      setChartData(result.data || []);
    } catch (err) {
      console.error("Failed to fetch chart data:", err);
      setError("Historical price data is currently unavailable for this timeframe.");
      setChartData([]);
    } finally {
      setLoading(false);
    }
  }, [metal, citySlug, unit, duration, purity]);

  // Fetch new data whenever controls change (including returning to initial duration)
  useEffect(() => {
    if (isFirstMount.current) {
      isFirstMount.current = false;
      return;
    }

    fetchChartData();
  }, [unit, duration, purity, fetchChartData]);

  return (
    <div>
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3 mb-5">
        <div>
          <h2 className="text-lg md:text-xl font-bold text-slate-900 dark:text-slate-100 flex items-center gap-2">
            <TrendingUp className="w-5 h-5 text-sky-600 dark:text-sky-400" />
            Historical Price Trend of {metalConfig.displayName} ({unit})
          </h2>
          <p className="text-xs text-slate-500 dark:text-slate-400 mt-0.5">
            Interactive multi-timeframe price chart with live spot movements
          </p>
        </div>
      </div>

      {/* Controls */}
      <HistoryControls
        purities={
          metal === "gold" && metalConfig.purityOptions.length > 0
            ? metalConfig.purityOptions
            : undefined
        }
        selectedPurity={metal === "gold" ? purity : undefined}
        onPurityChange={metal === "gold" ? setPurity : undefined}
        units={historyUnits}
        selectedUnit={unit}
        onUnitChange={setUnit}
        durations={CHART_DURATIONS}
        selectedDuration={duration}
        onDurationChange={setDuration}
      />

      {/* Chart */}
      <div className="mt-6">
        {error && chartData.length === 0 ? (
          <div className="h-80 flex items-center justify-center bg-slate-50 dark:bg-slate-950/80 border border-slate-200 dark:border-slate-800 rounded-xl">
            <div className="text-center px-4">
              <p className="text-slate-500 dark:text-slate-400 text-sm mb-3">{error}</p>
              <button
                onClick={fetchChartData}
                className="px-3 py-1.5 rounded-lg bg-sky-50 dark:bg-sky-500/15 hover:bg-sky-100 dark:hover:bg-sky-500/25 border border-sky-200 dark:border-sky-500/30 text-xs font-semibold text-sky-700 dark:text-sky-400 transition-colors"
              >
                Retry Loading
              </button>
            </div>
          </div>
        ) : (
          <HistoryChart
            data={chartData}
            loading={loading}
            metal={metal}
            duration={duration}
          />
        )}
      </div>
    </div>
  );
}

/**
 * Last10DaysTable Component
 * Displays price data for the last 10 days
 */

import type { MetalLast10Days, MetalPurity, Metal } from "../types";
import { METAL_CONFIG } from "../types";
import { formatPrice } from "../utils";
import { Calendar, ArrowUp, ArrowDown } from "lucide-react";

interface Last10DaysTableProps {
  data: MetalLast10Days;
}

function formatHistoricalDate(dateStr: string) {
  if (!dateStr) return "–";
  try {
    const d = new Date(dateStr);
    if (isNaN(d.getTime())) return dateStr;
    return d.toLocaleDateString("en-IN", {
      day: "2-digit",
      month: "short",
      year: "numeric",
    });
  } catch {
    return dateStr;
  }
}

export function Last10DaysTable({ data }: Last10DaysTableProps) {
  if (!data || !data.metal) {
    return (
      <div className="bg-slate-900 border border-slate-800 rounded-2xl p-6">
        <p className="text-rose-400 text-xs">Unable to display historical data</p>
      </div>
    );
  }

  const metalKey = data.metal.toLowerCase() as Metal;
  const metalConfig = METAL_CONFIG[metalKey];

  if (!metalConfig) {
    return (
      <div className="bg-slate-900 border border-slate-800 rounded-2xl p-6">
        <p className="text-rose-400 text-xs">Unable to display price table for metal: {data.metal}</p>
      </div>
    );
  }

  const hasGoldPurity = metalConfig.purityOptions.length > 0;

  // Get columns based on metal type
  const columns: { purity?: MetalPurity; unit?: string; label: string }[] = [];

  if (data.data.length > 0) {
    if (hasGoldPurity) {
      const purities: MetalPurity[] = ["24K", "22K"];
      purities.forEach((purity) => {
        columns.push({
          purity,
          label: `${purity} (1g)`,
        });
      });
    } else {
      const units = ["1g", "10g", "100g"];
      units.forEach((unit) => {
        columns.push({
          unit,
          label: `${unit} Rate`,
        });
      });
    }
  }

  return (
    <div className="bg-white dark:bg-slate-900/90 border border-slate-200 dark:border-slate-800 rounded-2xl p-5 md:p-6 shadow-sm dark:shadow-xl">
      <div className="flex items-center justify-between gap-3 mb-4">
        <div className="flex items-center gap-2">
          <Calendar className="w-5 h-5 text-sky-600 dark:text-sky-400" />
          <div>
            <h2 className="text-base md:text-lg font-bold text-slate-900 dark:text-slate-100">
              {metalConfig.displayName} Price Trend — Last 10 Days
            </h2>
            <p className="text-xs text-slate-500 dark:text-slate-400">
              Daily historical movement and price adjustments{data.cityName ? ` in ${data.cityName}` : ""}
            </p>
          </div>
        </div>

        <span className="text-xs text-slate-500 dark:text-slate-400 font-semibold uppercase">
          Unit: {data.unit || "1g"}
        </span>
      </div>

      <div className="overflow-x-auto">
        <table className="w-full text-left text-xs border border-slate-200 dark:border-slate-800 rounded-xl overflow-hidden divide-y divide-slate-200 dark:divide-slate-800">
          <thead className="bg-slate-50 dark:bg-slate-950 text-[11px] font-semibold text-slate-500 dark:text-slate-400 uppercase tracking-wider">
            <tr>
              <th className="py-2.5 px-4">Date</th>
              {columns.map((col, idx) => (
                <th key={idx} className="py-2.5 px-4 text-right">
                  {col.label}
                </th>
              ))}
              <th className="py-2.5 px-4 text-center">Daily Movement</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-200 dark:divide-slate-800/80">
            {data.data.map((day: any, idx: number) => {
              // Extract primary change info from 24K or first available column
              const mainPurityData = day["24K"] || day["22K"] || day["1g"];
              const change = mainPurityData?.change;
              const dir = mainPurityData?.changeDirection;
              const isUp = dir === "up";
              const isDown = dir === "down";

              return (
                <tr
                  key={day.date}
                  className={idx === 0 ? "bg-sky-50/50 dark:bg-slate-950/60 font-semibold" : "hover:bg-slate-50 dark:hover:bg-slate-800/30"}
                >
                  <td className="py-2.5 px-4 font-bold text-slate-800 dark:text-slate-200 tabular-nums">
                    {formatHistoricalDate(day.date)}
                  </td>

                  {columns.map((col, colIdx) => {
                    const priceInfo = col.purity ? day[col.purity] : day[col.unit!];
                    const price = priceInfo?.price !== undefined ? priceInfo.price : priceInfo;
                    const is24K = col.purity === "24K";

                    return (
                      <td key={colIdx} className="py-2.5 px-4 text-right tabular-nums">
                        {price !== undefined ? (
                          <span className={`font-bold ${is24K ? "text-amber-600 dark:text-amber-400" : "text-slate-900 dark:text-slate-100"}`}>
                            {formatPrice(price)}
                          </span>
                        ) : (
                          <span className="text-slate-400 dark:text-slate-500">—</span>
                        )}
                      </td>
                    );
                  })}

                  <td className="py-2.5 px-4 text-center tabular-nums">
                    {change !== undefined && change !== 0 ? (
                      <span
                        className={`inline-flex items-center gap-0.5 px-2 py-0.5 rounded text-xs font-semibold ${
                          isUp
                            ? "text-emerald-700 dark:text-emerald-400 bg-emerald-50 dark:bg-emerald-500/10"
                            : isDown
                            ? "text-rose-700 dark:text-rose-400 bg-rose-50 dark:bg-rose-500/10"
                            : "text-slate-600 dark:text-slate-400 bg-slate-100 dark:bg-slate-800"
                        }`}
                      >
                        {isUp ? <ArrowUp className="w-3 h-3" /> : isDown ? <ArrowDown className="w-3 h-3" /> : null}
                        {isUp ? "+" : ""}
                        {formatPrice(Math.abs(change))}
                      </span>
                    ) : (
                      <span className="text-slate-400 dark:text-slate-500 text-xs">— Flat</span>
                    )}
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>
    </div>
  );
}

import { Shield, BookOpen, TrendingUp, HelpCircle, Award, Scale } from "lucide-react";
import type { Metal } from "../types";

interface MetalInvestorGuideProps {
