'use client';

import React, { useState, useEffect } from 'react';

interface CompanyLogoProps {
  src?: string | null;
  symbol: string;
  name?: string;
  size?: 'sm' | 'md' | 'lg' | 'xl';
  className?: string;
}

export default function CompanyLogo({
  src,
  symbol,
  name,
  size = 'md',
  className = '',
}: CompanyLogoProps) {
  const [hasError, setHasError] = useState(false);

  // Reset error state if src changes (e.g. stock changes in modal)
  useEffect(() => {
    setHasError(false);
  }, [src]);

  const sizeClasses = {
    sm: 'w-7 h-7 text-[10px] rounded-lg',
    md: 'w-8 h-8 text-xs rounded-lg',
    lg: 'w-10 h-10 text-sm rounded-xl',
    xl: 'w-14 h-14 text-xl rounded-2xl',
  }[size];

  const initials = (symbol || 'ST').slice(0, 2).toUpperCase();

  // If valid src and hasn't errored out
  if (src && !hasError) {
    return (
      <div
        className={`relative ${sizeClasses} shrink-0 overflow-hidden flex items-center justify-center border border-slate-200/80 dark:border-slate-700/80 shadow-2xs transition-all ${className}`}
      >
        <img
          src={src}
          alt={name || symbol}
          loading="lazy"
          className="w-full h-full object-cover"
          onError={() => setHasError(true)}
        />
      </div>
    );
  }

  // Fallback Initials Avatar with clean styling
  return (
    <div
      className={`${sizeClasses} bg-slate-100 dark:bg-slate-800 border border-slate-200 dark:border-slate-700/60 flex items-center justify-center font-bold text-sky-600 dark:text-sky-400 group-hover:border-sky-500/50 group-hover:shadow-2xs transition-all shrink-0 select-none ${className}`}
      title={name || symbol}
    >
      {initials}
    </div>
  );
}

'use client';

import React, { useMemo } from 'react';
import {
  ResponsiveContainer,
  AreaChart,
  Area,
  XAxis,
  YAxis,
  Tooltip,
  CartesianGrid,
  Bar,
  ComposedChart,
} from 'recharts';
import { StockCandle } from '../types';
import { useTheme } from '@/components/theme/useTheme';

interface StockCandleChartProps {
  candles: StockCandle[];
  currencySymbol?: string;
  loading?: boolean;
  range?: string;
}

export default function StockCandleChart({
  candles,
  currencySymbol = '₹',
  loading = false,
  range,
}: StockCandleChartProps) {
  const { isDark } = useTheme();
  const gridStroke = isDark ? '#1E293B' : '#E2E8F0';
  const axisTextFill = isDark ? '#94A3B8' : '#64748B';
  const axisLineStroke = isDark ? '#334155' : '#CBD5E1';

  // Sanitize candles: discard non-positive close stubs (e.g. unpopulated market sessions)
  // and normalize open/high/low to ensure integrity
  const chartData = useMemo(() => {
    return (candles || [])
      .filter((c) => c && typeof c.close === 'number' && c.close > 0 && !isNaN(c.close))
      .map((c) => {
        const close = Number(c.close);
        const open = typeof c.open === 'number' && c.open > 0 ? c.open : close;
        const high = typeof c.high === 'number' && c.high > 0 ? Math.max(c.high, open, close) : Math.max(open, close);
        const low = typeof c.low === 'number' && c.low > 0 ? Math.min(c.low, open, close) : Math.min(open, close);
        return {
          ...c,
          open,
          high,
          low,
          close,
          volume: Number(c.volume || 0),
          isGreen: close >= open,
        };
      });
  }, [candles]);

  // Compute zoomed domain with proportional breathing room so price changes are prominently displayed
  const { minPrice, maxPrice } = useMemo(() => {
    if (!chartData.length) return { minPrice: 0, maxPrice: 100 };
    const min = Math.min(...chartData.map((c) => c.low));
    const max = Math.max(...chartData.map((c) => c.high));
    const delta = max - min;
    const padding = delta > 0 ? Math.max(delta * 0.08, min * 0.01) : min * 0.05;
    return {
      minPrice: Math.max(0, Math.floor(min - padding)),
      maxPrice: Math.ceil(max + padding),
    };
  }, [chartData]);

  const isOverallUp = useMemo(() => {
    if (chartData.length < 2) return true;
    return chartData[chartData.length - 1].close >= chartData[0].close;
  }, [chartData]);

  const isIntraday = useMemo(() => {
    return chartData.some((c) => c.date?.includes('T') || c.date?.includes(':'));
  }, [chartData]);

  // Compute clean, evenly-spaced trader intervals for the X-axis based on range
  const smartTicks = useMemo(() => {
    if (!chartData || chartData.length === 0) return [];
    if (chartData.length <= 6) return chartData.map((c) => c.date);

    const dur = (range || '').toLowerCase();

    // 1D (Intraday): 5 clean hourly ticks
    if (dur === '1d' || isIntraday) {
      const count = Math.min(5, chartData.length);
      const step = (chartData.length - 1) / (count - 1);
      return Array.from({ length: count }, (_, i) => chartData[Math.round(i * step)].date);
    }

    // 1W: 5 daily ticks
    if (dur === '1w') {
      const count = Math.min(5, chartData.length);
      const step = (chartData.length - 1) / (count - 1);
      return Array.from({ length: count }, (_, i) => chartData[Math.round(i * step)].date);
    }

    // 1M: 5 weekly ticks (spaced ~7 days apart)
    if (dur === '1m') {
      const count = 5;
      const step = (chartData.length - 1) / (count - 1);
      return Array.from({ length: count }, (_, i) => chartData[Math.round(i * step)].date);
    }

    // 3M: 5 bi-weekly ticks
    if (dur === '3m') {
      const count = 5;
      const step = (chartData.length - 1) / (count - 1);
      return Array.from({ length: count }, (_, i) => chartData[Math.round(i * step)].date);
    }

    // 6M: Monthly intervals (first candle of each month)
    if (dur === '6m') {
      const monthMap = new Map<string, string>();
      chartData.forEach((c) => {
        if (!c.date) return;
        const d = new Date(c.date);
        const key = !isNaN(d.getTime())
          ? `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}`
          : c.date.slice(0, 7);
        if (!monthMap.has(key)) monthMap.set(key, c.date);
      });
      const monthTicks = Array.from(monthMap.values());
      if (monthTicks.length <= 7) return monthTicks;
      return monthTicks.filter((_, idx) => idx % 2 === 0);
    }

    // 1Y: Bi-monthly intervals (6-7 clean month ticks)
    if (dur === '1y') {
      const monthMap = new Map<string, string>();
      chartData.forEach((c) => {
        if (!c.date) return;
        const d = new Date(c.date);
        const key = !isNaN(d.getTime())
          ? `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}`
          : c.date.slice(0, 7);
        if (!monthMap.has(key)) monthMap.set(key, c.date);
      });
      const monthTicks = Array.from(monthMap.values());
      if (monthTicks.length <= 7) return monthTicks;
      return monthTicks.filter((_, idx) => idx % 2 === 0);
    }

    // 5Y: 5 yearly ticks (first candle of each calendar year)
    if (dur === '5y') {
      const yearMap = new Map<number, string>();
      chartData.forEach((c) => {
        if (!c.date) return;
        const d = new Date(c.date);
        if (!isNaN(d.getTime())) {
          const yr = d.getFullYear();
          if (!yearMap.has(yr)) yearMap.set(yr, c.date);
        }
      });
      const yearTicks = Array.from(yearMap.values());
      if (yearTicks.length >= 2) return yearTicks;
    }

    // Fallback: 5 evenly spaced ticks
    const count = 5;
    const step = (chartData.length - 1) / (count - 1);
    return Array.from({ length: count }, (_, i) => chartData[Math.round(i * step)].date);
  }, [chartData, range, isIntraday]);

  // Format date for X-axis: clean months for 1Y/6M, clean years for 5Y, clean dates for 1M/3M, times for 1D
  const formatXAxis = useMemo(() => {
    return (val: string) => {
      try {
        const d = new Date(val);
        if (isNaN(d.getTime())) return val;
        const dur = (range || '').toLowerCase();

        if (dur === '1d' || isIntraday) {
          return d.toLocaleTimeString('en-IN', {
            hour: '2-digit',
            minute: '2-digit',
            hour12: false,
          });
        }

        if (dur === '5y') {
          return String(d.getFullYear());
        }

        if (dur === '1y' || dur === '6m') {
          const monthStr = d.toLocaleString('en-IN', { month: 'short' });
          if (d.getMonth() === 0) {
            return `${monthStr} '${String(d.getFullYear()).slice(-2)}`;
          }
          return monthStr;
        }

        return `${d.getDate()} ${d.toLocaleString('en-IN', { month: 'short' })}`;
      } catch {
        return val;
      }
    };
  }, [range, isIntraday]);

  if (loading) {
    return (
      <div className="h-64 sm:h-72 w-full flex items-center justify-center bg-slate-50 dark:bg-slate-950/60 rounded-xl border border-slate-200 dark:border-slate-800">
        <div className="text-xs text-slate-500 dark:text-slate-400 animate-pulse">Loading interactive chart...</div>
      </div>
    );
  }

  if (!chartData || chartData.length === 0) {
    return (
      <div className="h-64 sm:h-72 w-full flex items-center justify-center bg-slate-50 dark:bg-slate-950/60 rounded-xl border border-slate-200 dark:border-slate-800">
        <div className="text-xs text-slate-500 dark:text-slate-400">Historical price candles currently unavailable for this timeframe.</div>
      </div>
    );
  }

  const strokeColor = isOverallUp ? '#10B981' : '#F43F5E';
  const fillColor = isOverallUp ? '#10B981' : '#F43F5E';

  return (
    <div className="h-64 sm:h-72 w-full pt-2">
      <ResponsiveContainer width="100%" height="100%">
        <ComposedChart data={chartData} margin={{ top: 10, right: 10, left: 10, bottom: 0 }}>
          <defs>
            <linearGradient id="stockAreaGrad" x1="0" y1="0" x2="0" y2="1">
              <stop offset="5%" stopColor={fillColor} stopOpacity={0.25} />
              <stop offset="95%" stopColor={fillColor} stopOpacity={0.0} />
            </linearGradient>
          </defs>
          <CartesianGrid strokeDasharray="3 3" stroke={gridStroke} opacity={0.6} />
          <XAxis
            key={range || 'default'}
            dataKey="date"
            ticks={smartTicks.length > 0 ? smartTicks : undefined}
            tickFormatter={formatXAxis}
            interval={0}
            minTickGap={15}
            tick={{ fontSize: 10, fill: axisTextFill }}
            tickLine={{ stroke: axisLineStroke }}
            axisLine={{ stroke: axisLineStroke }}
          />
          <YAxis
            domain={[minPrice, maxPrice]}
            orientation="right"
            tick={{ fontSize: 10, fill: axisTextFill }}
            tickLine={{ stroke: axisLineStroke }}
            axisLine={{ stroke: axisLineStroke }}
            tickFormatter={(v) => `${currencySymbol}${Math.round(v).toLocaleString()}`}
            width={70}
          />
          <Tooltip
            content={({ active, payload }) => {
              if (active && payload && payload.length) {
                const data = payload[0].payload as StockCandle & { isGreen: boolean };
                const chg = data.close - data.open;
                const chgPct = data.open ? (chg / data.open) * 100 : 0;
                let formattedDate = data.date;
                try {
                  const d = new Date(data.date);
                  if (!isNaN(d.getTime())) {
                    if (isIntraday) {
                      formattedDate = `${d.getDate()} ${d.toLocaleString('en-IN', { month: 'short' })} ${d.toLocaleTimeString('en-IN', { hour: '2-digit', minute: '2-digit' })}`;
                    } else {
                      formattedDate = `${d.getDate()} ${d.toLocaleString('en-IN', { month: 'short', year: 'numeric' })}`;
                    }
                  }
                } catch {
                  // keep raw date
                }

                return (
                  <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-700 rounded-xl p-3 text-xs shadow-xl min-w-[160px]">
                    <div className="flex items-center justify-between gap-2 mb-2 pb-1.5 border-b border-slate-100 dark:border-slate-800">
                      <span className="text-[10px] text-slate-500 dark:text-slate-400 font-medium">{formattedDate}</span>
                      <span className={`text-[10px] font-bold px-1.5 py-0.5 rounded ${chg >= 0 ? 'bg-emerald-500/15 text-emerald-600 dark:text-emerald-400' : 'bg-rose-500/15 text-rose-600 dark:text-rose-400'}`}>
                        {chg >= 0 ? '+' : ''}{chgPct.toFixed(2)}%
                      </span>
                    </div>
                    <div className="flex justify-between gap-3 text-slate-700 dark:text-slate-300">
                      <span>Close:</span>
                      <span className="font-bold text-slate-900 dark:text-slate-100 tabular-nums">
                        {currencySymbol}{data.close?.toLocaleString()}
                      </span>
                    </div>
                    <div className="flex justify-between gap-3 text-slate-500 dark:text-slate-400 text-[11px]">
                      <span>Open:</span>
                      <span className="tabular-nums">{currencySymbol}{data.open?.toLocaleString()}</span>
                    </div>
                    <div className="flex justify-between gap-3 text-slate-500 dark:text-slate-400 text-[11px]">
                      <span>High:</span>
                      <span className="text-emerald-500 dark:text-emerald-400 tabular-nums">{currencySymbol}{data.high?.toLocaleString()}</span>
                    </div>
                    <div className="flex justify-between gap-3 text-slate-500 dark:text-slate-400 text-[11px]">
                      <span>Low:</span>
                      <span className="text-rose-500 dark:text-rose-400 tabular-nums">{currencySymbol}{data.low?.toLocaleString()}</span>
                    </div>
                    <div className="flex justify-between gap-3 text-slate-500 dark:text-slate-400 text-[10px] pt-1 mt-1 border-t border-slate-100 dark:border-slate-800">
                      <span>Volume:</span>
                      <span className="tabular-nums">{data.volume?.toLocaleString()}</span>
                    </div>
                  </div>
                );
              }
              return null;
            }}
          />
          <Area
            type="monotone"
            dataKey="close"
            stroke={strokeColor}
            strokeWidth={2}
            fill="url(#stockAreaGrad)"
          />
        </ComposedChart>
      </ResponsiveContainer>
    </div>
  );
}

'use client';

import React from 'react';
import {
  ShieldCheck,
  AlertTriangle,
  XCircle,
  ArrowUpRight,
  ArrowDownRight,
  Sparkles,
  Check,
  X,
  Trophy,
  BarChart2,
} from 'lucide-react';
import { StockItem } from '../types';
import { formatMarketCap } from '../utils/mappers';
import CompanyLogo from './CompanyLogo';

interface StockCardViewProps {
  stocks: StockItem[];
  onSelectStock: (stock: StockItem) => void;
}

function formatVolume(val: number | undefined): string {
  if (!val) return '—';
  if (val >= 1_000_000_000) return `${(val / 1_000_000_000).toFixed(1)}B`;
  if (val >= 1_000_000) return `${(val / 1_000_000).toFixed(1)}M`;
  if (val >= 1_000) return `${(val / 1_000).toFixed(0)}K`;
  return val.toLocaleString();
}

export default function StockCardView({ stocks, onSelectStock }: StockCardViewProps) {
  const getStatusBadge = (status: StockItem['complianceStatus']) => {
    switch (status) {
      case 'compliant':
        return (
          <span className="inline-flex items-center gap-1 px-2.5 py-0.5 rounded-full text-xs font-semibold bg-emerald-500/15 text-emerald-600 dark:text-emerald-400 border border-emerald-500/30">
            <ShieldCheck className="w-3.5 h-3.5" />
            100% Halal
          </span>
        );
      case 'doubtful':
        return (
          <span className="inline-flex items-center gap-1 px-2.5 py-0.5 rounded-full text-xs font-semibold bg-amber-500/15 text-amber-600 dark:text-amber-400 border border-amber-500/30">
            <AlertTriangle className="w-3.5 h-3.5" />
            Under Review
          </span>
        );
      case 'non_compliant':
        return (
          <span className="inline-flex items-center gap-1 px-2.5 py-0.5 rounded-full text-xs font-semibold bg-rose-500/15 text-rose-600 dark:text-rose-400 border border-rose-500/30">
            <XCircle className="w-3.5 h-3.5" />
            Non-Compliant
          </span>
        );
    }
  };

  const getRankBadge = (rank?: number) => {
    if (!rank) return null;
    if (rank <= 3) {
      return (
        <span className="inline-flex items-center gap-0.5 px-2 py-0.5 rounded-full text-[11px] font-extrabold bg-gradient-to-r from-amber-500/20 to-yellow-500/20 text-amber-600 dark:text-amber-400 border border-amber-500/30">
          <Trophy className="w-3 h-3 text-amber-500" />
          #{rank}
        </span>
      );
    }
    return (
      <span className="px-1.5 py-0.5 rounded text-[11px] font-bold text-slate-500 dark:text-slate-400 bg-slate-100 dark:bg-slate-800">
        #{rank}
      </span>
    );
  };

  if (stocks.length === 0) {
    return (
      <div className="bg-white dark:bg-slate-900 border border-slate-200 dark:border-slate-800 rounded-2xl p-12 text-center shadow-sm">
        <AlertTriangle className="w-10 h-10 text-amber-500 dark:text-amber-400 mx-auto mb-3 opacity-80" />
        <h3 className="text-base font-semibold text-slate-900 dark:text-slate-200 mb-1">
          No stocks match your filter criteria
        </h3>
        <p className="text-xs text-slate-500 dark:text-slate-400 max-w-md mx-auto">
          Try adjusting your search query, sector selection, or resetting the filters.
        </p>
      </div>
    );
  }

  return (
    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4 mb-6">
      {stocks.map((stock) => {
        const isPositive = stock.changePercent >= 0;
        const isZeroDebt = stock.shariah.debtRatioPercent === 0;
        const rank = stock.trader_indicators?.rank_in_country;
        const tier = stock.trader_indicators?.market_tier;
        const range52w = stock.trader_indicators?.range_52w_position;
        const currencySym = stock.currencySymbol || '﷼';

        let posPct = range52w !== undefined && range52w !== null ? range52w : null;
        if (posPct === null && stock.fundamentals.week52High > stock.fundamentals.week52Low) {
          posPct = Math.round(
            ((stock.price - stock.fundamentals.week52Low) /
              (stock.fundamentals.week52High - stock.fundamentals.week52Low)) *
              100
          );
        }

        return (
          <div
            key={stock.id}
            onClick={() => onSelectStock(stock)}
            className="bg-white dark:bg-slate-900/90 border border-slate-200 dark:border-slate-800 hover:border-slate-300 dark:hover:border-slate-700 rounded-2xl p-4 transition-all hover:bg-slate-50/60 dark:hover:bg-slate-850/50 cursor-pointer flex flex-col justify-between group shadow-sm"
          >
            <div>
              {/* Header: Avatar, Ticker, Exchange, Rank & Status */}
              <div className="flex items-start justify-between gap-2 mb-3">
                <div className="flex items-center gap-2.5">
                  <CompanyLogo
                    src={stock.logo_url}
                    symbol={stock.symbol}
                    name={stock.name}
                    size="lg"
                  />
                  <div>
                    <div className="flex items-center gap-1.5 flex-wrap">
                      <span className="font-bold text-slate-900 dark:text-slate-100 text-base group-hover:text-sky-600 dark:group-hover:text-sky-400 transition-colors">
                        {stock.symbol}
                      </span>
                      <span className="text-[10px] font-semibold text-slate-400 uppercase">
                        {stock.exchange}
                      </span>
                      {rank && getRankBadge(rank)}
                      {isZeroDebt && (
                        <span className="inline-flex items-center gap-0.5 px-1 py-0.2 bg-emerald-500/10 text-emerald-700 dark:text-emerald-300 text-[9px] font-semibold rounded border border-emerald-500/20">
                          <Sparkles className="w-2.5 h-2.5" /> 0-Debt
                        </span>
                      )}
                    </div>
                    <div className="text-xs text-slate-500 dark:text-slate-400 truncate max-w-[190px]" title={stock.name}>
                      {stock.name}
                    </div>
                  </div>
                </div>

                <div>{getStatusBadge(stock.complianceStatus)}</div>
              </div>

              {/* Price & Change Banner */}
              <div className="flex items-baseline justify-between p-3 bg-slate-50 dark:bg-slate-950/80 rounded-xl border border-slate-200 dark:border-slate-800/80 mb-3">
                <div>
                  <span className="text-[10px] font-bold text-slate-500 dark:text-slate-400 block uppercase tracking-wider">
                    Current Price
                  </span>
                  <span className="text-lg font-extrabold text-slate-900 dark:text-slate-100 tabular-nums">
                    {currencySym}{stock.price.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
                  </span>
                </div>
                <div className="text-right">
                  <span className="text-[10px] font-bold text-slate-500 dark:text-slate-400 block uppercase tracking-wider">
                    Day Move
                  </span>
                  <span
                    className={`inline-flex items-center gap-0.5 font-bold text-xs tabular-nums px-1.5 py-0.5 rounded ${
                      isPositive
                        ? 'bg-emerald-500/10 text-emerald-600 dark:text-emerald-400'
                        : 'bg-rose-500/10 text-rose-600 dark:text-rose-400'
                    }`}
                  >
                    {isPositive ? <ArrowUpRight className="w-3.5 h-3.5" /> : <ArrowDownRight className="w-3.5 h-3.5" />}
                    {isPositive ? '+' : ''}
                    {stock.changePercent.toFixed(2)}%
                  </span>
                </div>
              </div>

              {/* 52-Week Range Bar */}
              {posPct !== null && (
                <div className="mb-3 px-1">
                  <div className="flex justify-between text-[10px] text-slate-500 dark:text-slate-400 tabular-nums mb-1">
                    <span>52W Low: {currencySym}{stock.fundamentals.week52Low?.toFixed(1) || '–'}</span>
                    <span className="font-semibold text-slate-700 dark:text-slate-300">Pos: {posPct}%</span>
                    <span>High: {currencySym}{stock.fundamentals.week52High?.toFixed(1) || '–'}</span>
                  </div>
                  <div className="w-full bg-slate-200 dark:bg-slate-800 h-1.5 rounded-full overflow-hidden">
                    <div
                      className="bg-gradient-to-r from-sky-500 to-indigo-500 h-full rounded-full transition-all"
                      style={{ width: `${Math.min(100, Math.max(0, posPct))}%` }}
                    />
                  </div>
                </div>
              )}

              {/* Shariah Criteria Checklist */}
              <div className="space-y-1.5 text-xs mb-3 pt-2 border-t border-slate-100 dark:border-slate-800/80">
                <div className="flex items-center justify-between text-slate-600 dark:text-slate-400">
                  <span className="flex items-center gap-1.5">
                    {stock.shariah.businessActivityStatus === 'pass' ? (
                      <Check className="w-3.5 h-3.5 text-emerald-600 dark:text-emerald-400" />
                    ) : (
                      <X className="w-3.5 h-3.5 text-rose-600 dark:text-rose-400" />
                    )}
                    Business Activity:
                  </span>
                  <span
                    className={`font-semibold ${
                      stock.shariah.businessActivityStatus === 'pass'
                        ? 'text-emerald-600 dark:text-emerald-400'
                        : 'text-rose-600 dark:text-rose-400'
                    }`}
                  >
                    {stock.shariah.businessActivityStatus === 'pass' ? 'Halal Core' : 'Non-Permissible'}
                  </span>
                </div>

                <div className="flex items-center justify-between text-slate-600 dark:text-slate-400">
                  <span className="flex items-center gap-1.5">
                    {stock.shariah.debtRatioPercent <= 33 ? (
                      <Check className="w-3.5 h-3.5 text-emerald-600 dark:text-emerald-400" />
                    ) : (
                      <X className="w-3.5 h-3.5 text-rose-600 dark:text-rose-400" />
                    )}
                    Interest-Bearing Debt:
                  </span>
                  <span
                    className={`font-semibold tabular-nums ${
                      stock.shariah.debtRatioPercent <= 33
                        ? 'text-emerald-600 dark:text-emerald-400'
                        : 'text-rose-600 dark:text-rose-400'
                    }`}
                  >
                    {stock.shariah.debtRatioPercent}% (Max 33%)
                  </span>
                </div>
              </div>
            </div>

            {/* Footer Stats: Market Cap & Volume */}
            <div className="pt-3 border-t border-slate-200/80 dark:border-slate-800 flex items-center justify-between text-xs">
              <div>
                <span className="text-slate-500 dark:text-slate-400 block text-[10px] uppercase font-medium">Market Cap</span>
                <span className="font-bold text-slate-900 dark:text-slate-100 tabular-nums">
                  {formatMarketCap(stock.rawMarketCap || stock.marketCapCr * 10000000, stock.country)}
                </span>
              </div>
              <div className="text-right">
                <span className="text-slate-500 dark:text-slate-400 block text-[10px] uppercase font-medium">Vol</span>
                <span className="font-bold text-slate-900 dark:text-slate-100 tabular-nums">
                  {formatVolume(stock.volume)}
                </span>
              </div>
            </div>
          </div>
        );
      })}
    </div>
  );
}

