  searchQuery: string;
  onSearchChange: (val: string) => void;
  selectedSector: string;
  onSectorChange: (val: string) => void;
  selectedMarketTier: string;
  onMarketTierChange: (val: string) => void;
  selectedHalalStatus: 'ALL' | 'HALAL' | 'NON_HALAL' | 'DOUBTFUL';
  onHalalStatusChange: (val: 'ALL' | 'HALAL' | 'NON_HALAL' | 'DOUBTFUL') => void;
  sortField: string;
  sortOrder: 'ASC' | 'DESC';
  onSortChange: (field: string, order?: 'ASC' | 'DESC') => void;
  viewMode: 'table' | 'cards';
  onViewModeChange: (mode: 'table' | 'cards') => void;
  activePreset: string;
  onSelectPreset: (preset: string) => void;
  onResetFilters: () => void;
  totalFilteredCount: number;
  isLoading?: boolean;
}

const DEFAULT_PRESETS: StockFilterPreset[] = [
  { id: 'all', label: 'All Stocks' },
  { id: 'bluechips', label: 'Blue Chips' },
  { id: 'gainers', label: 'Top Gainers' },
  { id: 'losers', label: 'Dip Opportunities' },
  { id: 'most_active', label: 'Most Active' },
  { id: 'near_52w_high', label: 'Near 52W High' },
  { id: 'undervalued_growth', label: 'Undervalued PE < 20' },
  { id: 'high_dividend', label: 'High Dividend > 3%' },
  { id: 'halal_only', label: '100% Halal' },
];

export default function StockFilterBar({
  country,
  searchQuery,
  onSearchChange,
  selectedSector,
  onSectorChange,
  selectedMarketTier,
  onMarketTierChange,
  selectedHalalStatus,
  onHalalStatusChange,
  sortField,
  sortOrder,
  onSortChange,
  viewMode,
  onViewModeChange,
  activePreset,
  onSelectPreset,
  onResetFilters,
  totalFilteredCount,
  isLoading = false,
}: StockFilterBarProps) {
  const [config, setConfig] = useState<StockFiltersConfig | null>(null);

  useEffect(() => {
    let isMounted = true;
    async function loadConfig() {
      try {
        const res = await getFiltersConfig(country);
        if (isMounted && res) {
          setConfig(res);
        }
      } catch (err) {
        console.error('Failed to load filter config for', country, err);
      }
    }
    loadConfig();
    return () => {
      isMounted = false;
    };
  }, [country]);

  const presets = config?.presets?.length ? config.presets : DEFAULT_PRESETS;
  const sectors = config?.sectors || [];
  const marketTiers = config?.market_tiers || [
    { id: 'MEGA_CAP', label: 'Mega Cap' },
    { id: 'LARGE_CAP', label: 'Large Cap' },
    { id: 'MID_CAP', label: 'Mid Cap' },
    { id: 'SMALL_CAP', label: 'Small Cap' },
  ];
  const sortOptions = config?.sort_options || [
    { id: 'market_cap', label: 'Market Cap' },
    { id: 'latest_price', label: 'Price' },
    { id: 'change_percentage', label: '% Change' },
    { id: 'volume', label: 'Volume' },
    { id: 'pe_ratio', label: 'P/E Ratio' },
  ];

  const hasActiveFilters =
    Boolean(searchQuery.trim()) ||
    selectedSector !== 'All' ||
    selectedMarketTier !== 'All' ||
    selectedHalalStatus !== 'ALL' ||
    activePreset !== 'all';

  return (
    <div className="bg-white dark:bg-slate-900/90 border border-slate-200 dark:border-slate-800 rounded-2xl p-4 md:p-5 mb-6 shadow-sm space-y-4 transition-colors">
      {/* Row 1: Search + Filters Dropdowns + View Mode Switcher */}
      <div className="flex flex-col lg:flex-row gap-3 items-stretch lg:items-center justify-between">
        {/* Search Input */}
        <div className="relative flex-1">
          <Search className="absolute left-3.5 top-1/2 -translate-y-1/2 w-4 h-4 text-slate-400 dark:text-slate-500" />
          <input
            type="text"
            placeholder={`Search ${country} equities by ticker, name or sector...`}
            value={searchQuery}
            onChange={(e) => onSearchChange(e.target.value)}
            className="w-full pl-9 pr-14 py-2.5 bg-slate-50 dark:bg-slate-950/80 border border-slate-200 dark:border-slate-800 rounded-xl text-sm text-slate-900 dark:text-slate-100 placeholder-slate-400 dark:placeholder-slate-500 focus:outline-none focus:border-sky-500 focus:ring-2 focus:ring-sky-500/20 transition-all"
          />
          {searchQuery && (
            <button
              type="button"
              onClick={() => onSearchChange('')}
              className="absolute right-3 top-1/2 -translate-y-1/2 text-xs text-slate-400 hover:text-slate-600 dark:hover:text-slate-200 font-medium"
            >
              Clear
            </button>
          )}
        </div>

        {/* Dropdowns Row */}
        <div className="flex items-center gap-2 flex-wrap sm:flex-nowrap justify-between lg:justify-end">
          {/* Sector Dropdown */}
          <select
            value={selectedSector}
            onChange={(e) => onSectorChange(e.target.value)}
            aria-label="Filter by Sector"
            className="px-3 py-2 bg-slate-50 dark:bg-slate-950/80 border border-slate-200 dark:border-slate-800 rounded-xl text-xs font-medium text-slate-700 dark:text-slate-300 focus:outline-none focus:border-sky-500 transition-colors"
          >
            <option value="All">All Sectors</option>
            {sectors.map((sec) => (
              <option key={sec} value={sec}>
                {sec}
              </option>
            ))}
          </select>

          {/* Market Tier Dropdown */}
          <select
            value={selectedMarketTier}
            onChange={(e) => onMarketTierChange(e.target.value)}
            aria-label="Filter by Market Tier"
            className="px-3 py-2 bg-slate-50 dark:bg-slate-950/80 border border-slate-200 dark:border-slate-800 rounded-xl text-xs font-medium text-slate-700 dark:text-slate-300 focus:outline-none focus:border-sky-500 transition-colors"
          >
            <option value="All">All Tiers</option>
            {marketTiers.map((tier) => (
              <option key={tier.id} value={tier.id}>
                {tier.label}
              </option>
            ))}
          </select>

          {/* Shariah Status Dropdown */}
          <select
            value={selectedHalalStatus}
            onChange={(e) => onHalalStatusChange(e.target.value as any)}
            aria-label="Filter by Shariah Status"
            className="px-3 py-2 bg-slate-50 dark:bg-slate-950/80 border border-slate-200 dark:border-slate-800 rounded-xl text-xs font-medium text-slate-700 dark:text-slate-300 focus:outline-none focus:border-sky-500 transition-colors"
          >
            <option value="ALL">All Compliance</option>
            <option value="HALAL">100% Halal</option>
            <option value="DOUBTFUL">Under Review</option>
            <option value="NON_HALAL">Non-Compliant</option>
          </select>

          {/* Sort Option & Direction */}
          <div className="flex items-center rounded-xl border border-slate-200 dark:border-slate-800 bg-slate-50 dark:bg-slate-950/80 overflow-hidden">
            <select
              value={sortField}
              onChange={(e) => onSortChange(e.target.value, sortOrder)}
              aria-label="Sort By Field"
              className="px-2.5 py-2 bg-transparent text-xs font-medium text-slate-700 dark:text-slate-300 focus:outline-none border-r border-slate-200 dark:border-slate-800"
            >
              {sortOptions.map((opt) => (
                <option key={opt.id} value={opt.id}>
                  {opt.label}
                </option>
              ))}
            </select>
            <button
              type="button"
              onClick={() => onSortChange(sortField, sortOrder === 'ASC' ? 'DESC' : 'ASC')}
              title={`Sorting ${sortOrder === 'ASC' ? 'Ascending' : 'Descending'}. Click to toggle.`}
              className="p-2 text-slate-600 dark:text-slate-300 hover:text-sky-600 dark:hover:text-sky-400 hover:bg-slate-200/50 dark:hover:bg-slate-800/50 transition-colors"
            >
              <ArrowUpDown className="w-3.5 h-3.5" />
            </button>
          </div>

          {/* Reset Filters Button */}
          {hasActiveFilters && (
            <button
              type="button"
              onClick={onResetFilters}
              title="Reset all filters to default"
              className="p-2 text-slate-400 hover:text-slate-700 dark:hover:text-slate-200 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-xl transition-colors shrink-0"
            >
              <RotateCcw className="w-4 h-4" />
            </button>
          )}

          {/* View Mode Switcher: Table / Cards */}
          <div className="flex items-center bg-slate-100 dark:bg-slate-950 border border-slate-200 dark:border-slate-800 rounded-xl p-0.5 shrink-0">
            <button
              type="button"
              onClick={() => onViewModeChange('table')}
              className={`flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-semibold transition-all ${
                viewMode === 'table'
                  ? 'bg-sky-600 text-white shadow-xs'
                  : 'text-slate-500 dark:text-slate-400 hover:text-slate-800 dark:hover:text-slate-200'
              }`}
              title="Table View (Institutional)"
            >
              <Table className="w-3.5 h-3.5" />
              <span className="hidden sm:inline">Table</span>
            </button>
            <button
              type="button"
              onClick={() => onViewModeChange('cards')}
              className={`flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-semibold transition-all ${
                viewMode === 'cards'
                  ? 'bg-sky-600 text-white shadow-xs'
                  : 'text-slate-500 dark:text-slate-400 hover:text-slate-800 dark:hover:text-slate-200'
              }`}
              title="Cards View"
            >
              <LayoutGrid className="w-3.5 h-3.5" />
              <span className="hidden sm:inline">Cards</span>
            </button>
          </div>
        </div>
      </div>

      {/* Row 2: Dynamic Screener Presets (StockeZee-Style) + Count */}
      <div className="flex items-center justify-between gap-3 pt-3 border-t border-slate-200 dark:border-slate-800/80 overflow-x-auto no-scrollbar">
        <div className="flex items-center gap-1.5 flex-nowrap shrink-0">
          <span className="text-[11px] font-bold text-slate-500 dark:text-slate-400 uppercase tracking-wider mr-1 hidden sm:inline flex items-center gap-1">
            <Sparkles className="w-3 h-3 text-sky-500" />
            Presets:
          </span>
          {presets.map((tab) => {
            const isActive = activePreset === tab.id;
            return (
              <button
                key={tab.id}
                type="button"
                onClick={() => onSelectPreset(isActive && tab.id !== 'all' ? 'all' : tab.id)}
                className={`px-3 py-1 rounded-full text-xs whitespace-nowrap transition-all flex items-center gap-1.5 ${
                  isActive
                    ? 'bg-sky-500/15 text-sky-600 dark:text-sky-400 border border-sky-500/40 shadow-xs font-bold'
                    : 'bg-slate-50 dark:bg-slate-950 text-slate-600 dark:text-slate-400 border border-slate-200 dark:border-slate-800 hover:border-slate-300 dark:hover:border-slate-700 hover:text-slate-900 dark:hover:text-slate-200 font-medium'
                }`}
                title={tab.description || tab.label}
              >
                {isActive && <Check className="w-3 h-3 text-sky-500" />}
                <span>{tab.label}</span>
              </button>
            );
          })}
        </div>

        {/* Counter Badge */}
        <div className="text-xs text-slate-500 dark:text-slate-400 shrink-0 font-medium hidden md:block">
          {isLoading ? (
            <span className="animate-pulse">Loading {country} data...</span>
          ) : (
            <span>
              Showing <strong className="text-slate-900 dark:text-slate-100 font-bold">{totalFilteredCount}</strong> stocks
            </span>
          )}
        </div>
      </div>
    </div>
  );
}

'use client';

import React, { useState, useEffect } from 'react';
import { TrendingUp, TrendingDown, Activity, Flame, ChevronRight, Loader2, BarChart2 } from 'lucide-react';
import { MarketMoverItem } from '../types';
import { getMarketMovers } from '../api';
import { getCurrencySymbol } from '../utils/mappers';

interface StockMarketMoversProps {
  country: string;
  onSelectStock: (symbol: string) => void;
}

function formatVolume(val: number | string | undefined): string {
  if (!val) return '—';
  const num = typeof val === 'string' ? parseFloat(val) : val;
  if (isNaN(num)) return '—';
  if (num >= 1_000_000_000) return `${(num / 1_000_000_000).toFixed(1)}B`;
  if (num >= 1_000_000) return `${(num / 1_000_000).toFixed(1)}M`;
  if (num >= 1_000) return `${(num / 1_000).toFixed(0)}K`;
  return num.toLocaleString();
}

export default function StockMarketMovers({ country, onSelectStock }: StockMarketMoversProps) {
  const [moverType, setMoverType] = useState<'gainers' | 'losers' | 'active'>('gainers');
  const [movers, setMovers] = useState<MarketMoverItem[]>([]);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    let isMounted = true;
    async function loadMovers() {
      setLoading(true);
      try {
        const data = await getMarketMovers(country, moverType, 5);
        if (isMounted) {
          setMovers(data);
        }
      } catch (err) {
        console.error('Failed to load market movers:', err);
        if (isMounted) setMovers([]);
      } finally {
        if (isMounted) setLoading(false);
      }
    }

    loadMovers();
    return () => {
      isMounted = false;
    };
  }, [country, moverType]);

  const currencySym = getCurrencySymbol(country);

  return (
    <div className="bg-white dark:bg-slate-900/90 border border-slate-200 dark:border-slate-800 rounded-2xl p-4 shadow-sm mb-6 transition-colors">
      {/* Header & Tabs */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3 mb-3.5 pb-3 border-b border-slate-200 dark:border-slate-800/80">
        <div className="flex items-center gap-2.5">
          <div className="w-8 h-8 rounded-lg bg-amber-500/10 border border-amber-500/20 flex items-center justify-center shrink-0">
            <Flame className="w-4 h-4 text-amber-500 dark:text-amber-400" />
          </div>
          <div>
            <h2 className="text-sm font-bold text-slate-900 dark:text-slate-100 flex items-center gap-1.5">
              Market Movers ({country})
            </h2>
            <span className="text-[11px] text-slate-500 dark:text-slate-400">
              Live momentum leaders & high volume tickers
            </span>
          </div>
        </div>

        {/* Mover Tabs */}
        <div className="inline-flex rounded-xl border border-slate-200 dark:border-slate-800 bg-slate-100 dark:bg-slate-950 p-1">
          <button
            type="button"
            onClick={() => setMoverType('gainers')}
            className={`flex items-center gap-1.5 px-3 py-1 rounded-lg text-xs font-semibold transition-all ${
              moverType === 'gainers'
                ? 'bg-emerald-500/15 text-emerald-700 dark:text-emerald-300 border border-emerald-500/30 shadow-xs'
                : 'text-slate-500 dark:text-slate-400 hover:text-slate-900 dark:hover:text-slate-200'
            }`}
          >
            <TrendingUp className="w-3.5 h-3.5 text-emerald-600 dark:text-emerald-400" />
            <span>Top Gainers</span>
          </button>
          <button
            type="button"
            onClick={() => setMoverType('losers')}
            className={`flex items-center gap-1.5 px-3 py-1 rounded-lg text-xs font-semibold transition-all ${
              moverType === 'losers'
                ? 'bg-rose-500/15 text-rose-700 dark:text-rose-300 border border-rose-500/30 shadow-xs'
                : 'text-slate-500 dark:text-slate-400 hover:text-slate-900 dark:hover:text-slate-200'
            }`}
          >
            <TrendingDown className="w-3.5 h-3.5 text-rose-600 dark:text-rose-400" />
            <span>Top Losers</span>
          </button>
          <button
            type="button"
            onClick={() => setMoverType('active')}
            className={`flex items-center gap-1.5 px-3 py-1 rounded-lg text-xs font-semibold transition-all ${
              moverType === 'active'
                ? 'bg-sky-500/15 text-sky-700 dark:text-sky-300 border border-sky-500/30 shadow-xs'
                : 'text-slate-500 dark:text-slate-400 hover:text-slate-900 dark:hover:text-slate-200'
            }`}
          >
            <Activity className="w-3.5 h-3.5 text-sky-600 dark:text-sky-400" />
            <span>Most Active</span>
          </button>
        </div>
      </div>

      {/* Movers Cards Strip */}
      {loading ? (
        <div className="h-24 flex items-center justify-center text-xs text-slate-500 dark:text-slate-400 gap-2">
          <Loader2 className="w-4 h-4 animate-spin text-sky-600 dark:text-sky-400" />
          <span>Loading market movers for {country}...</span>
        </div>
      ) : movers.length > 0 ? (
        <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-5 gap-2.5">
          {movers.map((m, idx) => {
            const changePctNum = Number(m.change_percentage || 0);
            const isPositive = changePctNum >= 0;
            return (
              <div
                key={m.id || m.symbol}
                onClick={() => onSelectStock && onSelectStock(m.symbol)}
                className="bg-slate-50 dark:bg-slate-950/70 border border-slate-200 dark:border-slate-800/80 hover:border-slate-300 dark:hover:border-slate-700 p-3 rounded-xl cursor-pointer transition-all hover:bg-slate-100 dark:hover:bg-slate-800/40 group flex flex-col justify-between"
              >
                <div>
                  <div className="flex items-center justify-between gap-1 mb-1">
                    <div className="flex items-center gap-1.5">
                      <span className="text-[10px] font-bold px-1.5 py-0.5 rounded bg-slate-200/70 dark:bg-slate-800 text-slate-600 dark:text-slate-400">
                        #{idx + 1}
                      </span>
                      <span className="font-bold text-xs text-slate-900 dark:text-slate-100 group-hover:text-sky-600 dark:group-hover:text-sky-400 transition-colors">
                        {m.symbol}
                      </span>
                    </div>
                    <span className="text-[9px] font-semibold text-slate-500 uppercase px-1 py-0.5 rounded bg-slate-200/50 dark:bg-slate-800/60">
                      {m.exchange}
                    </span>
                  </div>
                  <p className="text-[11px] text-slate-500 dark:text-slate-400 truncate mb-2" title={m.company_name}>
                    {m.company_name}
                  </p>
                </div>

                <div className="pt-2 border-t border-slate-200/80 dark:border-slate-800/60">
                  <div className="flex items-baseline justify-between gap-1 mb-1">
                    <span className="text-xs font-bold text-slate-900 dark:text-slate-100 tabular-nums">
                      {currencySym}{Number(m.price || 0).toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
                    </span>
                    <span
                      className={`text-[11px] font-bold tabular-nums px-1.5 py-0.5 rounded ${
                        isPositive
                          ? 'bg-emerald-500/10 text-emerald-600 dark:text-emerald-400'
                          : 'bg-rose-500/10 text-rose-600 dark:text-rose-400'
                      }`}
                    >
                      {isPositive ? '+' : ''}{changePctNum.toFixed(2)}%
                    </span>
                  </div>
                  {m.volume && (
                    <div className="flex items-center justify-between text-[10px] text-slate-500 dark:text-slate-400">
                      <span>Vol:</span>
                      <span className="font-medium tabular-nums text-slate-600 dark:text-slate-400">
                        {formatVolume(m.volume)}
                      </span>
                    </div>
                  )}
                </div>
              </div>
            );
          })}
        </div>
      ) : (
        <div className="py-6 text-center text-xs text-slate-500">
          No mover data currently recorded for {country}. Track live listings below.
        </div>
      )}
    </div>
  );
}

'use client';

import React, { useEffect, useState } from 'react';
import { Layers, PieChart, Building2, BarChart2, CheckCircle2, ChevronRight, Loader2 } from 'lucide-react';
import { MarketOverviewData, MarketSectorOverview } from '../types';
import { getMarketOverview } from '../api';

interface StockMarketOverviewProps {
  country: string;
  selectedSector?: string;
  onSelectSector: (sector: string) => void;
}

export default function StockMarketOverview({
  country,
  selectedSector,
  onSelectSector,
}: StockMarketOverviewProps) {
  const [overview, setOverview] = useState<MarketOverviewData | null>(null);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    let isMounted = true;
    async function loadOverview() {
      setLoading(true);
      try {
        const data = await getMarketOverview(country);
        if (isMounted) {
          setOverview(data);
        }
      } catch (err) {
        console.error('Failed to load market overview:', err);
        if (isMounted) setOverview(null);
      } finally {
        if (isMounted) setLoading(false);
      }
    }

    loadOverview();
    return () => {
      isMounted = false;
    };
  }, [country]);

  if (loading && !overview) {
    return (
      <div className="bg-white dark:bg-slate-900/90 border border-slate-200 dark:border-slate-800 rounded-2xl p-5 mb-6 shadow-sm flex items-center justify-center gap-2 text-xs text-slate-500">
        <Loader2 className="w-4 h-4 animate-spin text-sky-600 dark:text-sky-400" />
        <span>Loading market breakdown for {country}...</span>
      </div>
    );
  }

  if (!overview || !overview.top_sectors || overview.top_sectors.length === 0) {
    return null;
  }

  const sumOfSectorCounts = overview.top_sectors.reduce((acc, s) => acc + (Number(s.count) || 0), 0);
  const parsedSummaryTotal = overview.summary?.[0]?.total_companies ? Number(overview.summary[0].total_companies) : 0;
  const totalStocks = Number(overview.total_stocks || 0) || parsedSummaryTotal || sumOfSectorCounts;
  const topSector = overview.top_sectors[0];
  const topSectorCount = topSector ? (Number(topSector.count) || 0) : 0;
  const topSectorPct = topSector?.percentage
    ? parseFloat(String(topSector.percentage))
    : totalStocks > 0
    ? parseFloat(((topSectorCount / totalStocks) * 100).toFixed(1))
    : 0;

  return (
    <div className="bg-white dark:bg-slate-900/90 border border-slate-200 dark:border-slate-800 rounded-2xl p-5 mb-6 shadow-sm transition-colors">
      {/* Header & High-Level Stats */}
      <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-4 pb-4 border-b border-slate-200 dark:border-slate-800/80">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 rounded-xl bg-gradient-to-tr from-sky-500/20 via-sky-500/10 to-indigo-500/10 dark:from-sky-500/30 dark:to-indigo-500/20 border border-sky-500/30 flex items-center justify-center text-sky-600 dark:text-sky-400 shrink-0">
            <PieChart className="w-5 h-5" />
          </div>
          <div>
            <div className="flex items-center gap-2">
              <h2 className="text-sm sm:text-base font-bold text-slate-900 dark:text-slate-100">
                Market Structure & Sector Breakdown
              </h2>
              <span className="text-[11px] font-semibold px-2 py-0.5 rounded-full bg-sky-500/10 text-sky-600 dark:text-sky-400 border border-sky-500/20">
                {country}
              </span>
            </div>
            <p className="text-xs text-slate-500 dark:text-slate-400 mt-0.5">
              Sectoral distribution & active equity concentration
            </p>
          </div>
        </div>

        {/* Quick Summary Badges */}
        <div className="flex flex-wrap items-center gap-2 sm:gap-3 text-xs">
          <div className="flex items-center gap-2 px-3 py-1.5 rounded-xl bg-slate-50 dark:bg-slate-950/70 border border-slate-200 dark:border-slate-800">
            <Building2 className="w-3.5 h-3.5 text-slate-500 dark:text-slate-400" />
            <span className="text-slate-500 dark:text-slate-400 font-medium">Tradable Stocks:</span>
            <span className="font-bold text-slate-900 dark:text-slate-100 tabular-nums">
              {totalStocks.toLocaleString()}
