                    ) : (
                      <span className="text-center block text-slate-400 text-xs">—</span>
                    )}
                  </td>

                  {/* Volume */}
                  <td className="px-3 py-3 text-right hidden xl:table-cell tabular-nums text-slate-600 dark:text-slate-400 font-medium">
